$f=new Finance($db,'fin');$bank=$f->createAccount('Test bank','offline','100','2026-01-01');$cash=$f->createAccount('Test cash','cash','20','2026-01-01');$data=['kind'=>'donation','description'=>'Test','counterparty'=>'Test','amount'=>'30','category'=>'donations','document_date'=>'2026-08-01','due_date'=>'2026-08-01'];$don=$f->createEntry($data,bin2hex(random_bytes(16)));$exp=$f->createEntry(array_replace($data,['kind'=>'expense','amount'=>'10']),bin2hex(random_bytes(16)));$o=$f->overview('2026-08-01','2026-08-31');check($o['funds']===12000&&$o['projected']===14000,'projected balance includes open receivables less payables while funds stay separate');
$f->recordPayment($don,1,$bank,'2026-08-05');$paid=$f->overview('2026-08-01','2026-08-31');check($paid['funds']===15000&&$paid['projected']===14000,'settlement moves from receivables to cash without doubling projected balance');
$totals=Finance::entryTotals($f->entries());check($totals['income']===3000&&$totals['expense']===1000&&$totals['remaining']===1000&&$totals['net']===2000,'list totals reconcile all matching receipt amounts');$f->cancel($exp,1);check(Finance::entryTotals($f->entries())['expense']===0,'cancelled receipt excluded from list totals');
